window.TP3B["camara:204553"] = [{"t":"PL","n":"5078","y":"2026","e":"Institui o Auxílio Emergencial às Famílias de Vítimas de Violência Urbana praticada por Agentes Públicos da União, dos Estados ou do Distrito Federal, destinado aos dependentes em situação de vulnerabilidade econômica, assegura a análise, a implantação e o primeiro pagamento no prazo de trinta dias contado do requerimento e regulamenta o art. 245 da Constituição Federal.","d":"2026-08-14","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-08-14","ds":"Apresentação do PL n. 5078/2026 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Institui o Auxílio Emergencial às Famílias de Vítimas de Violência Urbana praticada por Agentes Públicos da União, dos Estados ou do Distrito Federal, destinado aos dependentes em situação de vulnerabilidade econômica, assegura a análise, a implantação e o primeiro pagamento no prazo de trint","id":"2643797","law":false,"r":"m"},{"t":"PL","n":"5074","y":"2026","e":"Institui normas gerais de proteção econômica do militar dos Estados, do Distrito Federal e dos Territórios definitivamente incapacitado em decorrência do exercício da função ou em razão dela; Cria a complementação mensal dos proventos, para praças, equiparando a remuneração de referência do posto de capitão da respectiva instituição; para o oficial, equiparando a remuneração de referência do posto de coronel; com reforma as respectivas funções; altera o Decreto-Lei nº 667, de 2 de julho de 1969, e a Lei nº 14.751, de 12 de dezembro de 2023.","d":"2026-08-14","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-08-14","ds":"Apresentação do PL n. 5074/2026 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Institui normas gerais de proteção econômica do militar dos Estados, do Distrito Federal e dos Territórios definitivamente incapacitado em decorrência do exercício da função ou em razão dela; Cria a complementação mensal dos proventos, para praças, equiparando a remuneração de referência do p","id":"2643773","law":false,"r":"m"},{"t":"PL","n":"3505","y":"2026","e":"Altera a Lei nº 11.445, de 5 de janeiro de 2007, para instituir a Tarifa Social Institucional dos serviços públicos de abastecimento de água e esgotamento sanitário destinada aos templos de qualquer culto e às entidades privadas sem fins lucrativos que desenvolvam atividades de relevante interesse social para conceder desconto mínimo de cinquenta por cento incidente sobre as tarifas de abastecimento de água e esgotamento sanitário.","d":"2026-07-07","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-07-07","ds":"Apresentação do PL n. 3505/2026 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Altera a Lei nº 11.445, de 5 de janeiro de 2007, para instituir a Tarifa Social Institucional dos serviços públicos de abastecimento de água e esgotamento sanitário destinada aos templos de qualquer culto e às entidades privadas sem fins lucrativos que desenvolvam atividades de relevante inte","id":"2637475","law":false,"r":"m"},{"t":"PL","n":"3504","y":"2026","e":"Altera a Lei nº 11.445, de 5 de janeiro de 2007, para instituir a Política Nacional de Modicidade Tarifária dos Serviços de Esgotamento Sanitário, estabelecer o teto nacional de referência correspondente a 30% da tarifa de abastecimento de água, fortalecer a transparência regulatória, assegurar a proporcionalidade da cobrança e proteger os direitos dos usuários dos serviços públicos de saneamento básico.","d":"2026-07-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-07-06","ds":"Apresentação do PL n. 3504/2026 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Altera a Lei nº 11.445, de 5 de janeiro de 2007, para instituir a Política Nacional de Modicidade Tarifária dos Serviços de Esgotamento Sanitário, estabelecer o teto nacional de referência correspondente a 30% da tarifa de abastecimento de água, fortalecer a transparência regulatória, assegur","id":"2637474","law":false,"r":"m"},{"t":"PL","n":"3113","y":"2026","e":"Institui o Programa Nacional Parlamento Inclusivo, destinado à promoção da participação de pessoas com deficiência nas estruturas legislativas da União, dos Estados, do Distrito Federal e dos Municípios, e dá outras providências.","d":"2026-06-15","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-10-13","ds":"Recebimento pelo(a) CASP.","id":"2632434","law":false,"r":"m"},{"t":"PL","n":"3098","y":"2026","e":"Institui o Dia Nacional da Juventude Cristã, a ser celebrado, anualmente, no último sábado do mês de setembro e o inclui no Calendário Oficial de Eventos da União.","d":"2026-06-15","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-08-18","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 19/08/2026.","id":"2632312","law":false,"r":"m"},{"t":"PL","n":"3035","y":"2026","e":"Dispõe sobre o registro honorífico do posto ou da graduação correspondente aos proventos percebidos pelos militares da reserva remunerada e reformados das Forças Armadas, das Polícias Militares e dos Corpos de Bombeiros Militares, e dá outras providências.","d":"2026-06-10","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-09-04","ds":"Recebimento pelo(a) CSPCCO.","id":"2631372","law":false,"r":"m"},{"t":"PL","n":"2570","y":"2026","e":"Altera a Lei nº 9.503/1997 para dispor sobre a não aplicação da medida administrativa de remoção do veículo em determinadas hipóteses de estacionamento irregular, quando cessada imediatamente a infração antes do início do procedimento de guinchamento.","d":"2026-05-25","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-08-13","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 08/07/2026 a 13/08/2026). Não foram apresentadas emendas.","id":"2627397","law":false,"r":"m"},{"t":"PL","n":"2415","y":"2026","e":"Altera a Lei nº 9.504, de 30 de setembro de 1997, para instituir indenização aos cidadãos convocados pela Justiça Eleitoral para compor Mesas Receptoras de Votos e Juntas Eleitorais durante os processos eleitorais, plebiscitos e referendos.","d":"2026-05-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2026-06-25","ds":"Apensação desta proposição ao PL 4250/2021.","id":"2624971","law":false,"r":"m"},{"t":"PL","n":"2305","y":"2026","e":"Denomina “Missionários Daniel Berg e Gunnar Vingren” a Ferrovia Norte-Sul (EF-151).","d":"2026-05-11","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-08-11","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 02/07/2026 a 11/08/2026). Não foram apresentadas emendas.","id":"2623497","law":false,"r":"m"},{"t":"PEC","n":"8","y":"2026","e":"Altera o art. 228 da Constituição Federal para admitir, em caráter excepcional, a redução da maioridade penal em casos de crimes hediondos e de crueldade extrema contra pessoas e animais.","d":"2026-05-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-08-12","ds":"Designado Relator, Dep. Mendonça Filho (PL-PE), para a PEC 32/2015, ao qual esta proposição está apensada.","id":"2623400","law":false,"r":"c"},{"t":"PL","n":"1969","y":"2026","e":"Garante às mulheres do sexo biológico feminino o direito à não invasão de suas dependências sanitárias por mulheres de sexo biologicamente diverso, em locais públicos e privados de uso coletivo.","d":"2026-04-24","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-06-22","ds":"Apensação do PL 2088/2026 a esta proposição.","id":"2618304","law":false,"r":"m"},{"t":"PL","n":"1163","y":"2026","e":"Pune com aplicação de sanções e multas equivalente a 10% do capital social, cassação do alvará ou cancelamento da licença de funcionamento à elevação abusiva, especulativa e injustificada de preços na revenda de combustíveis e alimentos, em proteção ao consumidor e à ordem econômica.","d":"2026-03-13","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-05-04","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 17/04/2026 a 04/05/2026). Não foram apresentadas emendas.","id":"2608935","law":false,"r":"m"},{"t":"PL","n":"454","y":"2026","e":"Altera a Lei nº 13.819, de 26 de abril de 2019, para dispor sobre a atuação voluntária e complementar de líderes religiosos em situações de tentativa de suicídio e automutilação, sob coordenação das autoridades competentes.","d":"2026-02-10","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-03-12","ds":"Recebimento pelo(a) CSAUDE.","id":"2602294","law":false,"r":"m"},{"t":"PL","n":"453","y":"2026","e":"Estabelece a obrigatoriedade de inserção de selo, marca d’água ou aviso visível em vídeos, imagens, áudios e demais conteúdos digitais produzidos total ou parcialmente por sistemas de Inteligência Artificial e veiculados no Brasil, inclusive em redes sociais, plataformas digitais e aplicativos de mensagens, com o objetivo de prevenir a desinformação, proteger a honra, a imagem, a privacidade dos cidadãos e coibir usos nocivos da tecnologia e dá outras providências.","d":"2026-02-10","o":"status_not_published","s":"","tr":"Publicação de Proposição","u":"2026-03-25","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/03/2026.","id":"2602287","law":false,"r":"m"},{"t":"PL","n":"6407","y":"2025","e":"Institui o Dia Nacional da Ressurreição de Nosso Senhor e Salvador Jesus Cristo, a ser celebrado no Domingo de Páscoa, e dá outras providências.","d":"2025-12-15","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-04-14","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 25/03/2026 a 14/04/2026). Não foram apresentadas emendas.","id":"2596532","law":false,"r":"m"},{"t":"PL","n":"6308","y":"2025","e":"Dispõe sobre a proibição de concessão, renovação ou manutenção de porte e posse de arma de fogo, bem como o acesso a clubes ou estandes de tiro e a autorizações de caça, a pessoas com histórico de violência contra a mulher, crianças e adolescentes, e dá outras providências.","d":"2025-12-09","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-03-17","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 04/03/2026 a 17/03/2026). Não foram apresentadas emendas.","id":"2594679","law":false,"r":"m"},{"t":"PL","n":"6096","y":"2025","e":"Estabelece a suspensão e a perda da guarda e do poder familiar sobre crianças e adolescentes e/ou, quando seus pais, mães e responsáveis legais se acharem em situação de dependência química ou alcoolismo que coloque em risco os seus direitos fundamentais, estabelece procedimentos para a proteção integral, e dá outras providências.","d":"2025-12-02","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2591063","law":false,"r":"m"},{"t":"PL","n":"6087","y":"2025","e":"Institui o “Dia Nacional do Orgulho Heterossexual”, a ser comemorado anualmente no terceiro domingo de dezembro.","d":"2025-12-02","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2590981","law":false,"r":"m"},{"t":"PL","n":"5940","y":"2025","e":"Dispõe sobre a obrigatoriedade da prisão preventiva em crimes de violência física, sexual ou grave ameaça praticados contra a mulher, estabelece presunção legal de risco à vítima e restringe a concessão de liberdade do agressor.","d":"2025-11-24","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2026-03-13","ds":"Apensação desta proposição ao PL 4026/2025.","id":"2587107","law":false,"r":"m"},{"t":"PL","n":"5411","y":"2025","e":"Dispõe sobre a cooperação interestadual entre as Polícias Militares e Civis dos Estados e do Distrito Federal, para fins de operações conjuntas, diligências, perseguições imediata e continuada, investigações oficiais, e dá outras providências.","d":"2025-10-24","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-10-24","ds":"Apresentação do PL n. 5411/2025 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Dispõe sobre a cooperação interestadual entre as Polícias Militares e Civis dos Estados e do Distrito Federal, para fins de operações conjuntas, diligências, perseguições imediata e continuada, investigações oficiais, e dá outras providências. \n\".","id":"2576115","law":false,"r":"m"},{"t":"PEC","n":"34","y":"2025","e":"Acrescenta o inciso IX ao art. 225, §º1 da Constituição Federal, a alínea “e” ao inciso II do art. 9º, §3º e o §14 ao art. 9º da Emenda Constitucional 132/2023 para corrigir o tratamento injusto concedido pela Reforma Tributária aos agentes que atuam no setor de reciclagem, desvalorizando os materiais recicláveis e desincentivando a economia circular.","d":"2025-09-03","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-07-06","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 06/07/2026.","id":"2557024","law":false,"r":"c"},{"t":"PEC","n":"32","y":"2025","e":"Esta Lei altera o artigo 5º, inciso XLIII, da Constituição Federal, o qual prevê que nos casos de crimes previstos neste inciso, a pena deverá ser cumprida integralmente em regime fechado, por eles respondendo os mandantes, os executores e os que, podendo evitá-los, se omitirem, e dá outras providências.","d":"2025-08-20","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2026-09-01","ds":"Aprovado o requerimento nº 1/2026,da Sra. Talíria Petrone que requer a realização de Audiência Pública no âmbito da Comissão Especial sobre a redução da maioridade penal (PEC 32/2015) para debater a idade penal como cláusula pétrea e o controle de constitucionalidade da redução frente aos direitos e garantias individuais imutáveis da Constituição de 1988, sugerindo os seguintes especialistas: Dr. ","id":"2551011","law":false,"r":"c"},{"t":"PL","n":"3353","y":"2025","e":"Autoriza o Poder Público a cassar o alvará de funcionamento de estabelecimentos que comercializem combustíveis adulterados, mediante a constatação pela autoridade competente.","d":"2025-07-11","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2026-04-08","ds":"Desapensação deste do PL nº 399, de 2025, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 399, de 2025, adotado pelo relator da Comissão de Minas e Energia. (Sessão Deliberativa Extraordinária Presencial de 08/04/2026 - 13:55 - 47ª Sessão)","id":"2534897","law":false,"r":"m"},{"t":"PL","n":"3255","y":"2025","e":"Dispõe sobre o aumento de pena para crimes cometidos contra agentes da segurança pública no exercício de suas funções ou em razão delas, e dá outras providências.","d":"2025-07-03","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-13","ds":"Parecer do Relator, Dep. Waldemar Oliveira (AVANTE-PE), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação deste e do Projeto de Lei nº 6556/2025, apensado, nos termos do Substitutivo da Comissão de Segurança Pública e Combate ao Crime Organizado.","id":"2532008","law":false,"r":"m"},{"t":"PL","n":"2978","y":"2025","e":"Dispõe sobre a concessão de isenção do Imposto sobre Produtos Industrializados (IPI) na aquisição de novo veículo automotor por pessoa física que tenha sido vítima de furto ou roubo de veículo registrado em seu nome, e dá outras providências.","d":"2025-06-18","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-07-23","ds":"Recebimento pela CFT.","id":"2526992","law":false,"r":"m"},{"t":"PL","n":"2595","y":"2025","e":"Altera o artigo 392 da Consolidação das Leis do Trabalho - CLT, aprovada pelo Decreto-Lei nº 5.452, de 1º de maio de 1943, paraequipararo período da licença-maternidade de todas as trabalhadoras do setor privado ao das servidoras públicas que é de 180 (cento e oitenta) dias.","d":"2025-05-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Apresentação de Requerimento","u":"2025-08-18","ds":"Apresentação do REQ n. 3346/2025 (Requerimento de Apensação), pelo Deputado Vinicius Carvalho (REPUBLIC/SP), que \"Requer, nos termos regimentais, a tramitação conjunta dos Projetos de Lei nºs 2.595/2025, 2.169/2025, 2.558/2025, 1.900/2025, 1.059/2025, 3.781/2024, 3.008/2021 e 869/2024 com o Projeto de Lei nº 3.935/2008\n\".","id":"2517566","law":false,"r":"m"},{"t":"PL","n":"2162","y":"2025","e":"Estabelece critérios para a concessão da prisão domiciliar, vedando o cumprimento da pena em imóveis de luxo de propriedade do condenado ou de seus familiares, que representem ostentação desproporcional a natureza restritiva da medida e dá outras providências.","d":"2025-05-07","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-04-30","ds":"Designado Relator, Dep. Pedro Aihara (PP-MG).","id":"2505493","law":false,"r":"m"},{"t":"PEC","n":"17","y":"2025","e":"Acrescenta os §§ 11, 12 e 13 ao art. 144 da Constituição Federal, para instituir o piso salarial dos servidores policiais civis e militares e bombeiros militares.","d":"2025-04-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-04-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2499794","law":false,"r":"c"},{"t":"PL","n":"1658","y":"2025","e":"Dispõe sobre o uso e leitura da Bíblia Sagrada, seja evangélica ou católica, como recurso paradidático nas instituições de ensino públicas e privadas de todo o território nacional.","d":"2025-04-10","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-03-18","ds":"(Instalação da Comissão) O Relator, Dep. Capitão Alden, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2497137","law":false,"r":"m"},{"t":"PL","n":"1102","y":"2025","e":"Dispõe sobre a transformação das Guardas Municipais em Polícias Municipais nos municípios que dispuserem desta força e dá outras providências.","d":"2025-03-19","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-25","ds":"Designado Relator, Dep. Rodolfo Nogueira (PL-MS), para o PL 667/2025, ao qual esta proposição está apensada.","id":"2487584","law":false,"r":"m"},{"t":"PEC","n":"9","y":"2025","e":"Acrescenta o § 16 ao art. 198 da Constituição Federal, para dispor sobre as diretrizes para os Planos de Carreira e os pisos salariais nacionais dos profissionais de saúde do Sistema Único de Saúde.","d":"2025-02-27","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-10","ds":"Designado Relator, Dep. Coronel Assis (PL-MT).","id":"2485767","law":false,"r":"c"},{"t":"PEC","n":"8","y":"2025","e":"Dá nova redação ao inciso XIII, do artigo 7° da Constituição Federal para dispor sobre a redução da jornada de trabalho para quatro dias por semana no Brasil.","d":"2025-02-25","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2026-05-27","ds":"Desapensação desta da PEC nº 221, de 2019, principal, em face da aprovação, em Plenário, da Proposta de Emenda à Constituição n° 221, de 2019. (Sessão Deliberativa Extraordinária Presencial de 27/05/2026 - 15:00 - 106ª Sessão)","id":"2485341","law":false,"r":"c"},{"t":"PL","n":"532","y":"2025","e":"Dispõe sobre o reconhecimento dos cursos de formação de soldados e sargentos das Polícias Militares e Corpos de Bombeiros Militares como cursos superiores tecnólogos, facilitando a promoção ao oficialato superior, e dá outras providências.","d":"2025-02-18","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2025-05-06","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 25/04/2025 a 06/05/2025). Não foram apresentadas emendas.","id":"2484417","law":false,"r":"m"},{"t":"PL","n":"181","y":"2025","e":"Define o sexo de nascimento como o critério exclusivo para o uso de banheiros em escolas, espaços públicos, estabelecimentos comerciais e locais de trabalho, permitindo, adicionalmente, a implementação de banheiros unissex como opção complementar, desde que sejam preservados os banheiros masculinos e femininos.","d":"2025-02-04","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2025-12-18","ds":"Designada Relatora, Dep. Erika Kokay (PT-DF), para o PL 4019/2021, ao qual esta proposição está apensada.","id":"2482616","law":false,"r":"m"},{"t":"PL","n":"180","y":"2025","e":"Proíbe que com o uso de dinheiro público, hospitais, clínicas e estabelecimentos de saúde financiem ou realizem tratamentos hormonais, tanto indutores quanto bloqueadores, ou procedimentos cirúrgicos de redesignação sexual em menores de 18 anos, mesmo com o consentimento dos pais ou responsáveis, ressalvadas exceções para condições de saúde causadas por anomalias cromossômicas devidamente diagnosticadas.","d":"2025-02-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-12-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ), para o PL 3419/2019, ao qual esta proposição está apensada.","id":"2482615","law":false,"r":"m"},{"t":"PL","n":"5038","y":"2024","e":"Garante a isenção do Imposto sobre Produtos Industrializados (IPI) na aquisição de veículos automotores para motoristas de aplicativos (UBER, 99, CABIFY, INDRIVER entre outros) e mototaxistas, com o objetivo de equipará-los aos taxistas e dá outras providências.","d":"2024-12-20","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-03-13","ds":"Apensação da proposição PL 6524/2025 à proposição PL 914/2025.","id":"2481768","law":false,"r":"m"},{"t":"PL","n":"4183","y":"2024","e":"Garante o internamento voluntário de menores para tratar dependência química, bem como, a permanência, destes quando estejam sob a tutela de pais ou mães dependentes químicos em tratamento voluntário, de forma a garantir a continuidade do vínculo familiar durante o processo de recuperação, em instituições de tratamento credenciadas pelos órgãos públicos, assegurando ambiente apropriado e recursos especializados.","d":"2024-10-30","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2026-05-28","ds":"Desapensação deste do PL nº 1.822, de 2024, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 1.822, de 2024, adotado pelo relator da Comissão de Previdência, Assistência Social, Infância, Adolescência e Família. (Sessão Deliberativa Extraordinária Semipresencial de 28/05/2026 - 09:00 - 107ª Sessão)","id":"2466097","law":false,"r":"m"},{"t":"PEC","n":"29","y":"2024","e":"Altera a Constituição Federal para acrescentar no art. 5º texto sobre o marco temporal de início da vida humana explicitando de forma inequívoca a inviolabilidade do direito à vida, desde a sua concepção, bem como cria o inciso LXXX para especificar que a concepção é a junção do gameta masculino e o feminino, ocorrida durante a fecundação, em local propício para o desenvolvimento celular.","d":"2024-07-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-07-10","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2448752","law":false,"r":"c"},{"t":"PEC","n":"24","y":"2024","e":"Altera os §§ 4º, 4°-B e 7º do art. 40 da Constituição Federal e os artigos 5º, 10, 23, 24 e 26 da Emenda Constitucional nº 103, de 2019, acrescenta o art. 144-A a Constituição e dá outras providências.","d":"2024-06-24","o":"in_progress","s":"Aguardando Constituição de Comissão Temporária","tr":"Expedição de Documento","u":"2026-08-26","ds":"Ato da Presidência: Cria Comissão Especial, nos termos do § 2º do art. 202 do Regimento Interno. Publicado em DCD Extra no dia 26/08/2026.","id":"2442880","law":false,"r":"c"},{"t":"PL","n":"2462","y":"2024","e":"Garante em até 30 dias, a partir da data de óbito do beneficiário, a implantação e pagamento de benefício de pensão por morte às viúvas de policiais e bombeiros militares, policiais civis e penais, e demais integrantes da segurança pública, incluindo também todos os servidores públicos, sejam eles municipais, estaduais ou federais.","d":"2024-06-18","o":"in_progress","s":"Aguardando Designação - Aguardando Devolução de Relator(a) que deixou de ser Membro","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2026-02-04","ds":"O Relator, Dep. Sargento Portugal, deixou de ser membro da Comissão","id":"2441668","law":false,"r":"m"},{"t":"PL","n":"2369","y":"2024","e":"Proíbe a utilização de recursos da União, dos Estados e dos Municípios para subsidiar a implantação e utilização da linguagem neutra em documentos oficiais, materiais didáticos, comunicados, eventos, programas e quaisquer outras formas de comunicação oficial.","d":"2024-06-12","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-16","ds":"Designado Relator, Dep. Capitão Alden (PL-BA), para o PL 5198/2020, ao qual esta proposição está apensada.","id":"2440606","law":false,"r":"m"},{"t":"PL","n":"2363","y":"2024","e":"Dispõe sobre a não obrigatoriedade de utilização da linguagem neutra por parte dos cidadãos em suas falas e escritas, garantindo a liberdade de expressão, assegurando a todos os cidadãos o direito de escolherem a forma como se expressam.","d":"2024-06-12","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-02-25","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 19/12/2025 a 25/02/2026). Não foram apresentadas emendas.","id":"2440561","law":false,"r":"m"},{"t":"PL","n":"2322","y":"2024","e":"Isenta motocicletas em geral sejam: mototáxis, motoboys entre outras modalidades do pagamento de pedágios em todas as rodovias federais e estaduais do território nacional.","d":"2024-06-11","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-08-22","ds":"Designado Relator, Dep. Neto Carletto (AVANTE-BA).","id":"2439928","law":false,"r":"m"},{"t":"PL","n":"2321","y":"2024","e":"Institui o Dia Nacional dos valorosos e muito importantes Presbíteros, Diáconos e Diaconisas, autoridades eclesiásticas espirituais que sem a qual não seria possivel o crescimento da comunidade cristã no Brasil.","d":"2024-06-11","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-08-07","ds":"Encaminhada à publicação. Publicação Inicial no DCD 08/08/2024 PÁG 52.","id":"2439922","law":false,"r":"m"},{"t":"PL","n":"2319","y":"2024","e":"Institui o DIA NACIONAL DAS PASTORAS, a ser comemorado anualmente no dia 10 de maio, com o objetivo de reconhecer e valorizar a importância da atuação destas mulheres (líderes espirituais) no ministério pastoral no Brasil, e dá outras providências.","d":"2024-06-11","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-08-07","ds":"Encaminhada à publicação. Publicação Inicial no DCD 08/08/2024 PÁG 47.","id":"2439914","law":false,"r":"m"},{"t":"PL","n":"2283","y":"2024","e":"Institui o Benefício de Auxílio-Doença Parental no âmbito da Previdência Social, destinado ao segurado que possua dependentes com necessidades especiais ou que necessitem de internamento para tratamento de doenças graves, garantindo auxílio financeiro no valor de um salário-mínimo para sobrevivência do cuidador.","d":"2024-06-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-10-08","ds":"Devolvida à Relatora, Dep. Flávia Morais (PDT-GO), tendo em vista a apensação do PL 2.283/24. , para o PL 1876/2015, ao qual esta proposição está apensada.","id":"2439462","law":false,"r":"m"},{"t":"PL","n":"2281","y":"2024","e":"Obriga as empresas concessionárias de telefonia móvel (celular) a exemplo da TIM, VIVO, OI, CLARO entre outras, a implantarem torres ou equipamentos necessários para assegurar a comunicação dos seus consumidores nas rodovias estaduais e federais pedagiadas.","d":"2024-06-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-07","ds":"Designada Relatora, Dep. Dani Cunha (PL-RJ), para o PL 1721/2019, ao qual esta proposição está apensada.","id":"2439457","law":false,"r":"m"},{"t":"PL","n":"2280","y":"2024","e":"Obriga as concessionárias de pedágio a instalar torres ou equipamentos de telefonia móvel, necessários, que garantam aos usuários das rodovias estaduais e federais pedagiadas, sinal de celular ao longo de toda a sua extensão (OI, VIVO, TIM, CLARO entre outras) para assegurar a comunicação celular aos usuários que pagam pelo uso das vias.","d":"2024-06-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2024-07-30","ds":"Recebimento pela CASP.","id":"2439456","law":false,"r":"m"},{"t":"PL","n":"2164","y":"2024","e":"Proíbe a transação, venda de terrenos e propriedades, liberação de concessões para pedágios em orlas marítimas, fluviais, praias e espaços democráticos de lazer entre a União e entidades privadas como imobiliárias, clubes, parques aquáticos, condomínios ou demais empresas e dá outras providências.","d":"2024-06-04","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-02-10","ds":"Recebimento pelo(a) CASP.","id":"2437596","law":false,"r":"m"},{"t":"PL","n":"1825","y":"2024","e":"Garante assistência espiritual ou religiosa aos detentos, presos, e demais pessoas que estejam cumprindo pena privativa de liberdade em locais como: presídios, casas de detenção, delegacias, quarteis, instituições de medidas socioeducativas e outros onde existam confinamento de pessoas, em todo o território nacional, garantindo o direito das diversas fé e crenças religiosas.","d":"2024-05-15","o":"status_not_published","s":"","tr":"Publicação de Proposição","u":"2024-05-21","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 22/05/2024.","id":"2433782","law":false,"r":"m"},{"t":"PL","n":"1822","y":"2024","e":"Garante aos pais ou responsáveis a imediata internação de jovens e adolescentes, viciados em substancias psicoativas, em vulnerabilidade social, ou ameaçados de morte por traficantes e facções criminosas para tratamento da dependência química em entidades que tratem desta doença, legitimadas pelos poderes públicos Municipais, Estaduais e Federais e que comprovem ter em seus quadros profissionais do sistema único de assistência social como: psicólogos, assistentes sociais, e se possível de psiquiatria.","d":"2024-05-14","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-06-17","ds":"Remessa ao Senado Federal por meio do Of. nº 144/2026/SGM-P.","id":"2433663","law":false,"r":"m"},{"t":"PL","n":"1699","y":"2024","e":"Proíbe em shows ou quaisquer outros eventos públicos, a prática, simulação ou encenação de atos sexuais explícitos (seja ele: heterossexual, homossexual ou qualquer modalidade), de nudez, sexo oral, sexo anal, masturbação ou qualquer outro ato libidinoso em quaisquer espaços públicos ou acessíveis ao público, com a presença ou não de crianças e adolescentes, bem como estabelece medidas para prevenir a exposição indevida a conteúdo sexualmente explícito em ambientes não apropriados e dá outras providências.","d":"2024-05-08","o":"status_not_published","s":"","tr":"Apresentação de Requerimento","u":"2025-08-19","ds":"Apresentação do REQ n. 3395/2025 (Requerimento de Apensação), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Requer a apensação do Projeto de Lei nº 1.699/2024 ao Projeto de Lei nº 2.628/2022, por tratarem de matérias correlatas e se encontrarem em fase em que se permite apensação, nos termos regimentais\".","id":"2432352","law":false,"r":"m"},{"t":"PL","n":"1578","y":"2024","e":"Autoriza parlamentares estaduais e federais (Deputados Estaduais, Federais e Senadores), direcionarem verbas de emendas parlamentares para atender Estados da Federação em situação de desastres naturais, catástrofes, flagelo, calamidade pública decretada e outras emergências.","d":"2024-05-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2024-05-06","ds":"Apresentação do PL n. 1578/2024 (Projeto de Lei), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Autoriza parlamentares estaduais e federais (Deputados Estaduais, Federais e Senadores), direcionarem verbas de emendas parlamentares para atender Estados da Federação em situação de desastres naturais, catástrofes, flagelo, calamidade pública decretada e outras emergências\n\".","id":"2431110","law":false,"r":"m"},{"t":"PL","n":"1532","y":"2024","e":"Propõe isentar policiais e demais agentes da segurança pública, dos impostos sobre rendimentos a título de alimentação, transporte, fardamento e gratificações pagas para compensar os riscos da atividade.","d":"2024-05-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-06-11","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 12/06/2025, Letra A.","id":"2430837","law":false,"r":"m"},{"t":"PL","n":"246","y":"2024","e":"Visando coibir abusos na sala de aula, proíbe o uso indiscriminado de celulares e outros dispositivos eletrônicos pelos alunos nas unidades escolares públicas e privadas do Brasil e dá outras providências.","d":"2024-02-09","o":"prejudged","s":"Arquivada","tr":"Arquivamento","u":"2025-04-03","ds":"Declarada Prejudicada de Ofício pelo Presidente.","id":"2417829","law":false,"r":"m"},{"t":"PL","n":"6222","y":"2023","e":"Institui a obrigatoriedade da instalação de sistemas de câmeras de segurança em aeronaves, visando inibir agressões físicas e verbais, atos libidinosos, abusos e importunação sexual e possíveis práticas de pedofilia no interior das aeronaves operadas por companhias aéreas que atuam no território brasileiro, visando fortalecer as medidas de segurança e fornecer meios para investigação em casos relacionados à segurança aérea.","d":"2023-12-22","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-04-07","ds":"Designado Relator, Dep. Neto Carletto (PP-BA).","id":"2416609","law":false,"r":"m"},{"t":"PL","n":"6221","y":"2023","e":"Institui feriado nacional o dia 21 de outubro, “Dia Nacional de Valorização da Família”, com o propósito de fortalecer os vínculos familiares, valorizar a diversidade familiar, promover atividades positivas e reforçar os valores fundamentais para o desenvolvimento harmônico da sociedade.","d":"2023-12-22","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-05-20","ds":"Encaminhada à publicação. Parecer da Comissão de Trabalho Publicado em avulso e no DCD de 21/05/2026, Letra A.","id":"2416608","law":false,"r":"m"},{"t":"PL","n":"6218","y":"2023","e":"Institui feriado nacional o dia 30 de novembro, “Dia Nacional do Evangélico e do Cristão”, e altera o Artigo 1º da Lei nº 12.328, de 15 de setembro de 2010, para incluir o termo “do Cristão” em seu caput.","d":"2023-12-22","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-02-07","ds":"Recebimento pela CTRAB.","id":"2416597","law":false,"r":"m"},{"t":"PL","n":"6215","y":"2023","e":"Institui feriado nacional o segundo domingo do mês de dezembro, “Dia da Bíblia”, reconhecendo sua importância na formação da identidade cultural e histórica do Brasil.","d":"2023-12-22","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-02-27","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 28/02/2024 PAG 366","id":"2416571","law":false,"r":"m"},{"t":"PL","n":"6180","y":"2023","e":"Declara os eventos e movimentos evangélicos que acontecem no “DIA DA BÍBLIA” e no “DIA DOS EVANGÉLICOS”, como bem Imaterial e Cultural da Nação Brasileira e autoriza a destinação de recursos públicos das esferas Municipal, Estadual, Distrital e Federal para apoio na realização e estrutura destes eventos.","d":"2023-12-21","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-08-12","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 07/07/2026 a 12/08/2026). Não foram apresentadas emendas ao substitutivo.","id":"2416335","law":false,"r":"m"},{"t":"PL","n":"6171","y":"2023","e":"Declara o \"Círculo de Oração\" (Reunião de Mulheres de Oração) em todo o Brasil, Patrimônio Cultural e Imaterial da Nação.","d":"2023-12-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-23","ds":"Designado Relator, Dep. Raimundo Santos (PSD-PA), para o PL 3456/2023, ao qual esta proposição está apensada.","id":"2416287","law":false,"r":"m"},{"t":"PL","n":"5957","y":"2023","e":"Dispõe sobre a isenção do pagamento de pedágio em todo o território brasileiro para pessoas portadoras de deficiência, doença grave ou em tratamento médico fora do seu domicílio, devidamente cadastradas no CADÚNICO - Cadastro Único para Programas Sociais, incluindo os veículos condutores de tais pacientes e dá outras providências.","d":"2023-12-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-09-16","ds":"Designado Relator, Dep. Pinheirinho (PP-MG), para o PL 4016/2015, ao qual esta proposição está apensada.","id":"2412115","law":false,"r":"m"},{"t":"PL","n":"5833","y":"2023","e":"Estabelece margem de preferência para as propostas oferecidas por pessoas de baixa renda, na aquisição de materiais e equipamentos sem utilização previsível vendidos pela administração pública.","d":"2023-12-04","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-06-06","ds":"Encaminhada à publicação. Parecer da Comissão de Finanças e Tributação Publicado em avulso e no DCD de 07/06/2025 PÁG 793, Letra A.","id":"2408923","law":false,"r":"c"},{"t":"PL","n":"5699","y":"2023","e":"Proíbe a prática de atos lascivos, obscenos, indecentes, devassos, libidinosos, libertinos ou similares a práticas sexuais em espaços de uso público, (bares, restaurantes, shoppings center, demais estabelecimentos comerciais e ruas, praças, avenidas, parques, praias, transportes públicos, entre outros) independentemente da orientação sexual, e determina penalidades para os infratores.","d":"2023-11-24","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-05-28","ds":"Designado Relator, Dep. Capitão Alberto Neto (PL-AM), para o PL 6831/2010, ao qual esta proposição está apensada.","id":"2406637","law":false,"r":"m"},{"t":"PL","n":"5320","y":"2023","e":"Altera a Lei nº 8.078, de 11 de setembro de 1990 (Código de Defesa do Consumidor), para estabelecer a obrigatoriedade de compensação proporcional aos consumidores pelas companhias aéreas em caso de atraso de voos superiores a uma hora.","d":"2023-11-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-11-10","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 11/11/2023.","id":"2401091","law":false,"r":"m"},{"t":"PEC","n":"34","y":"2023","e":"Inclui dispositivos nos artigos 3º e 5º da Constituição da República Federativa do Brasil, estabelecendo o combate às drogas ilícitas como princípio fundamental e vedando expressamente a descriminalização do tráfico e a legalização de novas drogas recreativas.","d":"2023-08-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) A Relatora, Dep. Caroline de Toni, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2377463","law":false,"r":"c"},{"t":"PL","n":"3091","y":"2023","e":"Proíbe a participação ou exploração de crianças e adolescentes menores de 16 anos ou suas imagens em qualquer evento ou local público ou privado, envolvendo conteúdos que proporcione ou incentive a sexualização precoce e a erotização desses menores.","d":"2023-06-14","o":"status_not_published","s":"","tr":"Apresentação de Requerimento","u":"2025-08-19","ds":"Apresentação do REQ n. 3394/2025 (Requerimento de Apensação), pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Requer a apensação do Projeto de Lei nº 3.091/2023 ao Projeto de Lei nº 2628/2022, por tratarem de matérias correlatas e se encontrarem em fase em que se permite apensação, nos termos regimentais\".","id":"2369439","law":false,"r":"m"},{"t":"PL","n":"2038","y":"2022","e":"Estende a assistência financeira prevista no inciso IV do art. 5º, da PEC nº 15/2022, aos motoristas de aplicativo, de transporte escolar ou de turismo e quaisquer profissionais que utilizem veículo automotor como instrumento de trabalho.","d":"2022-07-14","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-04-22","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 10/04/2026 a 22/04/2026). Não foram apresentadas emendas ao substitutivo.","id":"2332572","law":false,"r":"m"},{"t":"PL","n":"1984","y":"2022","e":"Estabelece o direito a acompanhante nas consultas, exames e nos casos de internação e procedimentos hospitalares.","d":"2022-07-12","o":"status_not_published","s":"","tr":"Apensação","u":"2025-12-22","ds":"Apensação da proposição PL-5522/2025 à proposição PL-935/2023.","id":"2332249","law":false,"r":"m"},{"t":"PEC","n":"18","y":"2022","e":"Acrescenta o § 9º-A ao art. 198 da Constituição Federal, para criar piso salarial diferenciado para os agentes comunitários de saúde e os agentes de combate às endemias detentores de formação técnica, nos termos que especifica.","d":"2022-07-08","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2026-03-20","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 21/03/2026, Letra A.","id":"2332037","law":false,"r":"c"},{"t":"PEC","n":"17","y":"2022","e":"Visa a atualização e capacitação tecnológica das Forças Armadas, alterando o art. 167 da Constituição Federal, para retirar a limitação de dotações consignadas ao orçamento das Forças Armadas e acrescentando o art. 101 ao Ato das Disposições Constitucionais Transitórias, para vedar, quaisquer limitações à execução das dotações.","d":"2022-06-15","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2024-04-23","ds":"Parecer da Relatora, Dep. Bia Kicis (PL-DF), pela admissibilidade.","id":"2329063","law":false,"r":"c"},{"t":"PLP","n":"34","y":"2022","e":"Torna privativo a Oficial General da Ativa das Forças Armadas, MARINHA, EXÉRCITO E AERONÁUTICA, a nomeação para o COMANDO DO MINISTÉRIO DA DEFESA, obedecendo ao rodízio entre as Forças Militares Brasileira.","d":"2022-03-23","o":"in_progress","s":"Aguardando Deliberação de Recurso","tr":"Apresentação de Recurso","u":"2022-04-18","ds":"Apresentação do Recurso n. 2/2022, pelo Deputado Pastor Sargento Isidório (AVANTE/BA), que \"Recurso contra a devolução do PLP nº 34 de 2022\".","id":"2318493","law":false,"r":"m"},{"t":"PL","n":"4274","y":"2021","e":"Considera a Convenção Estadual das Assembleias de Deus no Estado da Bahia (CEADEB), seus eventos e manifestações culturais e religiosas como Patrimônio Cultural de Natureza Material e Imaterial do Brasil.","d":"2021-12-02","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2025-09-25","ds":"Devolvida pelo Relator sem Manifestação.","id":"2310245","law":false,"r":"m"},{"t":"PL","n":"4273","y":"2021","e":"Altera a Lei no 10.741, de 1º de outubro de 2003, Estatuto do Idoso, para dispor sobre o encaminhamento do idoso ao Ministério Público.","d":"2021-12-02","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-04-23","ds":"Designado Relator, Dep. Zé Haroldo Cathedral (PSD-RR), para o PL 4253/2019, ao qual esta proposição está apensada.","id":"2310233","law":false,"r":"c"},{"t":"PL","n":"3933","y":"2021","e":"Prevê a possibilidade de condenação ao encarceramento vitalício pela prática do crime hediondo de feminicídio.","d":"2021-11-08","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2022-06-01","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 02/06/2022 PAG 802","id":"2306127","law":false,"r":"m"},{"t":"PL","n":"3329","y":"2021","e":"Autoriza a realização / incursão de missões religiosas de todas as religiões fundadas em preceitos / valores como solidariedade, amor ao próximo e senso de justiça, com destaque para as Cristãs em aldeias indígenas em todo território nacional, desde que salvaguardadas premissas sanitárias (atuais protocolos da FUNAI) e a costumeira relação amistosa e contribuitiva do Povo de Deus para com os povos originários","d":"2021-09-27","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2024-05-22","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 07/05/2024 a 22/05/2024). Não foram apresentadas emendas.","id":"2300498","law":false,"r":"m"},{"t":"PL","n":"3127","y":"2021","e":"Altera o artigo 6º da Lei nº 8.080 / 1990 incluindo no campo de atuação do SUS especificadamente a SAÚDE DO HOMEM de modo que toda organização do Sistema Único de Saúde, bem como planejamento, assistência e articulação interfederativa à passe a conferir uma nova e mais apropriada abordagem aos diagnósticos e às enfermidades típicas masculinas","d":"2021-09-13","o":"status_not_published","s":"","tr":"Notificações","u":"2024-12-09","ds":"Designado Relator, Dep. Diego Garcia (REPUBLIC-PR), para o PL 6568/2013, ao qual esta proposição está apensada.","id":"2298435","law":false,"r":"m"},{"t":"PL","n":"2649","y":"2021","e":"Garante a todas as Policiais Militares, Civis, Penitenciárias, Rodoviárias, Federais e Guardas Municipais do sexo feminino do Brasil o direito de se abster de realizar abordagem em homens fantasiados de mulher ou que se intitule como Trans ou Travestis, sejam eles hetero ou homossexual.","d":"2021-08-03","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Notificações","u":"2025-12-16","ds":"Memo nº 216/25 à CMULHER - solicitando a devolução da proposição.","id":"2291993","law":false,"r":"m"},{"t":"PL","n":"2504","y":"2021","e":"Estabelece o pagamento de dois salários mínimos às mulheres gestantes desempregadas e um salário mínimo e meio às mulheres gestantes empregadas, enquanto perdurarem os efeitos da pandemia do novo coronavírus.","d":"2021-07-09","o":"archived_reason_not_stated","s":"Arquivada","tr":"Devolução à CCP","u":"2023-10-25","ds":"Devolução à CCP, em virtude da aprovação do Req. nº 2.504/2021.","id":"2290286","law":false,"r":"m"},{"t":"PL","n":"1767","y":"2021","e":"Cria programa especial de inclusão para Enfermeiros nos cursos de medicina com financiamento do Governo Federal, por conta da escassez de profissionais de Medicina em nossa nação, visando ampliar o número de profissionais de medicina, no momento grave que a saúde pública atravessa no Brasil.","d":"2021-05-11","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2024-06-04","ds":"Parecer da Relatora, Dep. Franciane Bayer (REPUBLIC-RS), pela aprovação deste, na forma do Substitutivo da Comissão de Seguridade Social e Família.","id":"2282260","law":false,"r":"m"},{"t":"PL","n":"1241","y":"2021","e":"Autoriza o Poder Executivo Federal criar o programa de apoio de benefícios aos Profissionais de Segurança Pública da ativa que atuam no combate à COVID (PAPSP-COVID), destinado aos profissionais de Segurança Pública que estejam trabalhando nas atividades diretamente ligadas ao enfrentamento da pandemia Covid-19.","d":"2021-04-06","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2024-06-25","ds":"Arquivado","id":"2276719","law":false,"r":"m"},{"t":"PL","n":"1003","y":"2021","e":"Inclui os profissionais de segurança pública em todo o país, sejam eles, Policiais e Bombeiros Militares, Policiais Civis, Policiais Federais, Policiais Rodoviários Federais e Estaduais e/ou integrantes das Guardas Nacionais nas estruturas médicas hospitalares que cuidam da saúde dos integrantes das mui dignas FFAA. Tais profissionais gozarão de atendimento, tratamento e todo suporte médico-hospitalar na qualificada rede de hospitais das Forças Armadas.","d":"2021-03-22","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2021-07-01","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 02/07/21 PAG 277","id":"2274577","law":false,"r":"m"},{"t":"PL","n":"832","y":"2021","e":"Estabelece o novo Auxílio Emergencial no valor de R$ 600,00 e/ou até R$ 1.200,00 reais, aproveitando parte da Lei nº 13.982, de 2 de abril de 2020, esta ajuda financeira será paga conforme regra do Ministério da Cidadania que através desse benefício socorrerá todos os prejudicados pela pandemia Covid-19, enquanto está durar em solo brasileiro.","d":"2021-03-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Encerramento de Prazo","u":"2023-10-24","ds":"Encerramento automático do Prazo de Recurso 24/10/2023 21:22:00. Não foram apresentados recursos.","id":"2273546","law":false,"r":"m"},{"t":"PL","n":"654","y":"2021","e":"Inclui cultos, adorações e demais atividades em templos religiosos Cristãos Evangélicos, Católicos e de outros credos religiosos no rol das atividades essenciais, ampliando e incluindo na abrangência da Lei nº 13.979, de 6 de fevereiro de 2020, estes segmentos de atividades ou movimentos espirituais tornando-os essenciais a qualquer tempo, incluindo períodos de pandemia, catástrofe e qualquer outro evento danoso na nossa Nação.","d":"2021-03-02","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Despacho","u":"2025-05-13","ds":"Despacho exarado ao REQ n. 1.907/2023, conforme seguinte teor: \"Não conheço do Requerimento n.1.907/2023 quanto aos Projetos de Lei de números 714/2020, 933/2020,1.296/2020, 1.417/2020, 1.565/2020, 1.721/2020, 1.876/2020, 2.103/2020, 2.214/2020, 2.243/2020,2.411/2020, 2.416/2020, 2.519/2020, 2.520/2020, 2.653/2020,2.671/2020, 3.142/2020, 3.206/2020, 3.437/2020, 3.766/2020,4.070/2020, 4.187/2020 e ","id":"2271150","law":false,"r":"m"},{"t":"PL","n":"169","y":"2021","e":"Protege os trabalhadores brasileiros e regula o encerramento das atividades de empresas estrangeiras no Brasil e prevê garantias para o pagamento dos créditos indenizatórios, trabalhistas e tributários, visando a proteção das trabalhadoras e trabalhadores brasileiros.","d":"2021-02-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-03-05","ds":"Devolvida pelo Relator sem Manifestação.","id":"2268863","law":false,"r":"m"},{"t":"PL","n":"4867","y":"2020","e":"Proíbe o confisco de mercadorias legais de vendedores ambulantes, camelôs, vendedores informais em vias públicas em todo território nacional","d":"2020-10-08","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-07-18","ds":"Designada Relatora, Dep. Flávia Morais (PDT-GO), para o PL 10193/2018, ao qual esta proposição está apensada.","id":"2264210","law":false,"r":"m"},{"t":"PL","n":"4631","y":"2020","e":"Prevê o pagamento de gratificação aos mesários que trabalharem nas eleições municipais de 2020, para estimular e incentivar o voluntariado uma vez que os integrantes das salas de votações serão expostos ao grande número de eleitores, pondo-os em risco de contágio da Covid-19.","d":"2020-09-17","o":"archived_reason_not_stated","s":"Arquivada","tr":"Publicação de Proposição","u":"2021-10-22","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 23/10/21 PAG 55","id":"2263026","law":false,"r":"m"},{"t":"PL","n":"3891","y":"2020","e":"Estabelece a redução de 50% dos salários dos políticos, de Vereador a Presidente da República, Ministros, Secretários e demais autoridades das cúpulas dos Três Poderes da União, Estados e Distrito Federal e Municípios, enquanto perdurar o estado de calamidade pública em razão do Covid-19, tudo em benefício dos mais carentes da nossa nação.","d":"2020-07-21","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2020-07-21","ds":"Apresentação do Projeto de Lei n. 3891/2020, pelo Deputado Pastor Sargento Isidório  (AVANTE/BA), que \"Estabelece a redução de 50% dos salários dos políticos, de Vereador a Presidente da República, Ministros, Secretários e demais autoridades das cúpulas dos Três Poderes da União, Estados e Distrito Federal e Municípios, enquanto perdurar o estado de calamidade pública em razão do Covid-19, tudo em","id":"2258349","law":false,"r":"m"},{"t":"PL","n":"2832","y":"2020","e":"Garantir durante a pandemia (COVID 19) a rodoviários (motoristas), cobradores de ônibus, operadores de caixa de supermercados, bancos, e outros, bem como, trabalhadores similares expostos ao público durante a jornada de trabalho, proteção contra a transmissão/infecção.","d":"2020-05-21","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2023-06-01","ds":"Arquivado","id":"2253513","law":false,"r":"m"},{"t":"PL","n":"2831","y":"2020","e":"Prevê o pagamento do auxílio de R$600,00 até dezembro de 2020.","d":"2020-05-21","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2021-08-19","ds":"Arquivado","id":"2253512","law":false,"r":"m"},{"t":"PL","n":"2486","y":"2020","e":"Estabelece que o pagamento do auxílio emergencial de R$ 600,00, R$ 1.200,00 ou outros valores poderá ser feito em qualquer banco público ou privado, inclusive com a utilização de caixas eletrônicos, de agentes lotéricos e correspondentes bancários.","d":"2020-05-08","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2021-08-19","ds":"Arquivado","id":"2251984","law":false,"r":"m"},{"t":"PL","n":"2485","y":"2020","e":"Estabelece a regra da escolha em lista tríplice do Diretor-Geral da Polícia Federal, do Diretor-Geral da Polícia Rodoviária Federal, dos Comandantes das Polícias Militares e dos Corpos de Bombeiros Militares e dos Chefes das Polícias Judiciárias.","d":"2020-05-08","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Retirada pelo(a) Autor(a)","u":"2023-10-09","ds":"Retirado o PL n. 2485/2020, em razão do deferimento do Requerimento n. REQ 3472/2023, nos termos do artigo 104, caput, combinado com o artigo 114, VII, ambos do RICD.","id":"2251983","law":false,"r":"m"},{"t":"PL","n":"2015","y":"2020","e":"Altera o Decreto o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 para duplicar as penas de crimes contra a administração pública quando estes forem praticados por ocasião de calamidade púbica.","d":"2020-04-17","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2020-09-01","ds":"Desapensação automática deste do PL 1.485/2020, principal, em face da declaração de prejudicialidade deste e do seu consequente arquivamento (Sessão Deliberativa Extraordinária Virtual de 1º/9/2020 - 11h - 107ª Sessão).","id":"2249958","law":false,"r":"m"},{"t":"PL","n":"1766","y":"2020","e":"Isenta de pagamento de tarifas de energia elétrica e fornecimento de água todos templos religiosos cristãos evangélicos, católicos, de matriz africana e de qualquer outra denominação religiosa, bem como de hospitais filantrópicos, casas de acolhimento, instituições filantrópicas destinadas ao acolhimento de idosos e crianças, comunidades terapêuticas e demais instituições que prestem assistência ou atendimento a pessoas carentes.","d":"2020-04-09","o":"archived_reason_not_stated","s":"Arquivada","tr":"Publicação de Proposição","u":"2022-03-15","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 16/03/2022 PAG 439","id":"2247341","law":false,"r":"m"},{"t":"PL","n":"1517","y":"2020","e":"Isenta a cobrança de pedágio, enquanto durar a pandemia do novo coronavírus, nas rodovias estaduais e federais em todo território nacional para os caminhoneiros e para os profissionais considerados essenciais envolvidos no combate direto do COVID-19, quando legitimados pelas autoridades governamentais e Ministério da Saúde.","d":"2020-04-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-02-24","ds":"Designado Relator, Dep. Neto Carletto (AVANTE-BA), para o PL 725/2020, ao qual esta proposição está apensada.","id":"2243030","law":false,"r":"m"},{"t":"PL","n":"544","y":"2020","e":"Altera a Lei nº 8.213, de 24 de 1991, que dispõe sobre os Planos de Benefícios da Previdência Social, para garantir que seja automaticamente deferido o pedido do benefício para os cidadãos necessitados, nos casos em que a análise do INSS demore mais de 45 dias, visando eliminar prejuízos aos contribuintes.","d":"2020-03-04","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-04-06","ds":"O Relator, Dep. Alfredo Gaspar, deixou de ser membro da Comissão","id":"2238471","law":false,"r":"m"},{"t":"PL","n":"6349","y":"2019","e":"Institui mecanismos de depósito em conta vinculada dos encargos trabalhistas oriundos da contratação de mão-de-obra terceirizada da União, dos Estados e dos Municípios, protegendo os direitos trabalhistas, encargos sociais dentre outros dos   prestadores de serviços, terceirizados em nossa nação.","d":"2019-12-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-03-25","ds":"Designado Relator, Dep. Helder Salomão (PT-ES), para o PL 6456/2016, ao qual esta proposição está apensada.","id":"2233102","law":false,"r":"m"},{"t":"PL","n":"5787","y":"2019","e":"Obriga os hipermercados, supermercados, e demais lojas de varejo a contratarem trabalhadores para oferecer os serviços de empacotamento dos produtos adquiridos pelos clientes, proibindo também a exploração da mão de obra de servidores (caixas de fila), forçados a desenvolverem também a importante função de embaladores.","d":"2019-10-30","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-05","ds":"Designado Relator, Dep. Alfredinho (PT-SP), para o PL 353/2011, ao qual esta proposição está apensada.","id":"2227754","law":false,"r":"m"},{"t":"PL","n":"5623","y":"2019","e":"Garante aos consumidores de combustíveis uma melhor visualização, aferição e controle nas bombas de abastecimento, em todo território nacional, na hora da compra pela implantação de novas e seguras mangueiras transparentes.","d":"2019-10-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-06-11","ds":"Devolvido ao Relator, Dep. Roberto Monteiro Pai (PL-RJ), para o PL 4326/2019, ao qual esta proposição está apensada.","id":"2226431","law":false,"r":"m"},{"t":"PL","n":"5622","y":"2019","e":"Altera a Lei nº 13.640, de 2018, para reconhecer a relação de emprego entre o motorista de aplicativo e a empresas que operam o aplicativo.","d":"2019-10-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-05-30","ds":"Designado Relator, Dep. Augusto Coutinho (REPUBLIC-PE), para o PL 5069/2019, ao qual esta proposição está apensada.","id":"2226430","law":false,"r":"m"},{"t":"PL","n":"5351","y":"2019","e":"Dispõe sobre a proibição do uso de recursos públicos federais para contratação de artistas que em suas músicas, condutas corporais, danças e/ou coreografias desvalorizem, incentivem a violência e/ou exponham as mulheres a situação de constrangimento","d":"2019-10-02","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-25","ds":"Designada Relatora, Dep. Delegada Ione (PL-MG), para o PL 5941/2013, ao qual esta proposição está apensada.","id":"2223597","law":false,"r":"m"},{"t":"PL","n":"5350","y":"2019","e":"Proíbe aumento de preços nas praças de pedágios em rodovias federais, estaduais e transportes hidroviários fiscalizados e/ou sob tutela dos Estados, União, municípios e/ou Distrito Federal nos fins de semana e feriados.","d":"2019-10-02","o":"in_progress","s":"Pronta para Pauta","tr":"Notificações","u":"2025-12-02","ds":"Informativo CONOF","id":"2223596","law":false,"r":"m"},{"t":"PL","n":"5212","y":"2019","e":"Altera a Lei nº. 8.989, de 1995, para isentar profissionais que trabalham com motocicletas, a exemplo de mototaxista, motoboy e outros de pagamento do Imposto sobre Produtos Industrializados - IPI, na aquisição de motocicletas para o transporte de passageiros, \"mototaxista\",   \"motoboy\"  e \"courrier\" em entrega de mercadorias/documentos em serviço comunitário de rua, e altera a Lei nº 7.689, de 1998, para aumentar de 15% para 25% a alíquota da contribuição social sobre o lucro das instituições financeiras.","d":"2019-09-24","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2019-10-18","ds":"Recebimento pela CFT.","id":"2221700","law":false,"r":"m"},{"t":"PL","n":"4773","y":"2019","e":"COM VISTAS A EVITAR ESTÍMULOS À PEDOFILIA TÃO PREJUDICIAL À NOSSA SOCIEDADE, fica proibida a exposição de crianças e adolescentes em danças eróticas, com ou sem letras musicais pejorativas, com duplo sentido, que estimule, incentive ou faça apologia à sexualização precoce no âmbito de escolas públicas ou privadas, em programas de TV ou quaisquer outros ambientes públicos.","d":"2019-08-29","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2021-07-16","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 17/07/21 PAG 48","id":"2217825","law":false,"r":"m"},{"t":"PL","n":"4651","y":"2019","e":"Altera a Lei nº 9.933, de 1999, para estabelecer a competência concorrente do INMETRO e das entidades de metrologia dos Estados e do Distrito Federal para exercer o poder de polícia administrativa, expedir regulamentos técnicos nas áreas de avaliação da conformidade de produtos, insumos e serviços, e instituir e cobrar diretamente a Taxa de Serviços Metrológicos.","d":"2019-08-21","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2019-09-18","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 19/09/19 PÁG 598.","id":"2216784","law":false,"r":"m"},{"t":"PL","n":"4606","y":"2019","e":"Veda qualquer alteração, edição, supressão, adição ou adaptação aos textos dos livros da Bíblia Sagrada, mantendo a inviolabilidade de capítulos e versículos proibindo modificar o texto sagrado garantindo a pregação do seu conteúdo em todo territorio nacional.\n\nNOVA EMENTA: Veda qualquer alteração, adaptação, edição, supressão ou adição nos textos da Bíblia Sagrada, para manter a inviolabilidade de seus capítulos e versículos, e garante a pregação do seu conteúdo em todo o território nacional.","d":"2019-08-20","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Remessa ao Senado Federal","u":"2022-11-29","ds":"Remessa ao Senado Federal por meio do Of. nº 599/2022/SGM-P.","id":"2216376","law":false,"r":"m"},{"t":"PDL","n":"484","y":"2019","e":"Visando não prejudicar Entidades Filantrópicas ou Sociedade do Terceiro Setor, susta os efeitos da Portaria STN nº 233, de 15 de abril de 2019, que estabelece regra transitória em razão da necessidade de definição de rotinas e contas contábeis, bem como classificações orçamentárias para operacionalização do item 04.01.02.01 (3) da 9ª edição do Manual de Demonstrativos Fiscais (MDF), aprovado pela Portaria STN nº 389, de 14 de junho de 2018.","d":"2019-07-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2020-01-16","ds":"Recebimento pela CCJC, apensado ao PDL-212/2019","id":"2211926","law":false,"r":"m"},{"t":"PDL","n":"403","y":"2019","e":"Susta os efeitos do Decreto não numerado, que admitiu no Quadro Suplementar da Ordem de Rio Branco o Sr. Olavo Luiz Pimentel de Carvalho.","d":"2019-06-17","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2019-07-01","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 02/07/19 PÁG 100.","id":"2208415","law":false,"r":"m"},{"t":"PL","n":"3068","y":"2019","e":"Altera a Lei nº. 9.503, 1997, que instituiu o Código de Trânsito Brasileiro, para proibir a apreensão e a remoção de veículo que não possua o Certificado de Registro e Licenciamento de veículos (CRLV) em razão de débito com o Imposto sobre a propriedade de veículos automotores (IPVA), prejudicando o verdadeiro proprietário do bem.","d":"2019-05-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2019-10-25","ds":"Recebimento pela CVT, apensado ao PL-8494/2017","id":"2204344","law":false,"r":"m"},{"t":"PL","n":"3058","y":"2019","e":"Altera a Lei nº 13.260, de 2001, que dispõe sobre o Fundo de Financiamento ao estudante do Ensino Superior (FIES), para criar novas regras de proteção aos estudantes prevendo o refinanciamento dos contratos em atraso e proibindo a negativação dos estudantes e dos que concluíram o curso.","d":"2019-05-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2021-03-09","ds":"Apense-se a este(a) o(a) PL-5511/2020.","id":"2204305","law":false,"r":"m"},{"t":"PL","n":"2588","y":"2019","e":"Institui a Política Nacional de Redução dos Preços do Gás Liquefeito de Petróleo para Uso Residencial por Consumidores de Baixa Renda.","d":"2019-04-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-03-25","ds":"Designado Relator, Dep. Helder Salomão (PT-ES), para o PL 4995/2016, ao qual esta proposição está apensada.","id":"2199673","law":false,"r":"m"},{"t":"PL","n":"2587","y":"2019","e":"Altera a Lei nº 4.119, de 1962, que dispõe sobre os cursos de formação em Psicologia e regulamenta a profissão de Psicólogo para permitir o atendimento a casos de problemas de ajustamento e transtornos psicológicos, inclusive os relacionados a identidade de gênero e à orientação sexual.","d":"2019-04-29","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2025-03-25","ds":"Devolvida pelo Relator sem Manifestação.","id":"2199671","law":false,"r":"m"},{"t":"PL","n":"2387","y":"2019","e":"Proíbe a queima de pneus e outros objetos correlatos que causem prejuízos à saúde e ao meio ambiente, inclusive, em manifestações públicas em todo Território Brasileiro.","d":"2019-04-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2019-05-24","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 25/05/19 PÁG 25.","id":"2198592","law":false,"r":"m"},{"t":"PL","n":"2261","y":"2019","e":"Transfere por um dia no ano, (22 de abril) data do Descobrimento do Brasil, a sede do Governo Brasileiro para a Cidade de Porto Seguro na Bahia tornando-a a Capital Federal da nossa Nação simbolicamente por um dia, com vistas a dinamizar o turismo regional e resgatar elos históricos advindos desde o Descobrimento. Além de conferir ao Sul do Estado Baiano o destaque necessário e merecido em nível nacional.","d":"2019-04-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2019-05-08","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 09/05/19 PÁG 415.","id":"2197833","law":false,"r":"m"},{"t":"PL","n":"2223","y":"2019","e":"Majora as alíquotas de contribuições sociais sobre operações de produção e comercialização pelos cervejeiros, vinícolas e indústrias afins, no mercado interno e de importação de bebidas alcoólicas e destina recursos para ações de saúde e segurança pública relacionadas ao atendimento de pacientes de alcoolismo e de dependência química, bem como de suas famílias.","d":"2019-04-10","o":"rejected","s":"Arquivada","tr":"Arquivamento","u":"2023-02-02","ds":"Arquivado nos termos do art. 54, combinado com o § 4º do artigo 58 do RICD (Inadequação financeira e orçamentária).","id":"2197678","law":false,"r":"m"},{"t":"PL","n":"2200","y":"2019","e":"Dispõe sobre a proibição da participação de atletas transexuais do sexo masculino (HOMENS TRAVESTIDOS OU FANTASIADOS DE MULHER) em competições do sexo feminino em todo o Território Nacional.","d":"2019-04-10","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-09-01","ds":"Apensação da proposição PL 3112/2026 à proposição PL 2216/2026.","id":"2197492","law":false,"r":"m"},{"t":"PL","n":"2179","y":"2019","e":"Declara o evento \"MARCHA PARA JESUS\" Bem Imaterial e Cultural da Nação Brasileira e autoriza a destinação de recursos públicos das esferas Municipal, Estadual, Distrital e Federal para apoio na realização do evento.","d":"2019-04-09","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Apresentação de Proposição","u":"2026-06-11","ds":"Remessa ao Senado Federal por meio do Of. nº 388/2026/PS-GSE.","id":"2197389","law":false,"r":"m"},{"t":"PL","n":"2083","y":"2019","e":"Indicar diretrizes para o atendimento das Comunidades Terapêuticas como Política Pública permanente no Território Nacional, que garante o cuidado de qualidade aos pacientes com dependência química, em regime de residência transitória, instituindo como a Rede de Atenção Psicossocial no âmbito do Sistema Único de Saúde (SUS), na Política Nacional de Assistência Social - PNAS e no Sistema Nacional de Políticas Públicas sobre Drogas - SISNAD.","d":"2019-04-04","o":"archived_reason_not_stated","s":"Arquivada","tr":"Arquivamento","u":"2023-09-13","ds":"Arquivado","id":"2197028","law":false,"r":"m"},{"t":"PEC","n":"38","y":"2019","e":"Altera o art. 14 da Constituição e o Ato das Disposições Constitucionais Transitórias (ADCT) para possibilitar o pronto retorno ao serviço ativo dos militares brasileiros após mandatos eletivos.","d":"2019-04-02","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2023-11-21","ds":"Designado Relator, Dep. Alencar Santana (PT-SP)","id":"2196315","law":false,"r":"m"},{"t":"PL","n":"1787","y":"2019","e":"Altera a Lei nº 13.301, de 27 de junho de 2016, e a Lei nº 13.146, de 6 de julho de 2015, para ampliar os direitos de mães, pais e crianças vítimas de microcefalia e sequelas neurológicas decorrentes de doenças transmitidas pelo Aedes aegypti.","d":"2019-03-27","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2023-12-12","ds":"Desapensação deste do PL nº 3.974, de 2015, proposição principal, em face da aprovação da matéria, em Plenário, na forma do Substitutivo ao Projeto de Lei nº 3.974, de 2015, adotado pelo relator da Comissão de Finanças e Tributação (Sessão Deliberativa Extraordinária de 12/12/2023 - 13h55 - 270ª Sessão).","id":"2195599","law":false,"r":"c"},{"t":"PL","n":"1257","y":"2019","e":"Dispõe sobre a obrigatoriedade da execução do Hino Nacional Brasileiro pelos Vereadores, Deputados Estaduais, Deputados Federais, Deputados Distritais e Senadores da República no início dos trabalhos legislativos.","d":"2019-02-27","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-08-22","ds":"Designado Relator, Dep. Capitão Alberto Neto (PL-AM), para o PL 1131/2019, ao qual esta proposição está apensada.","id":"2193393","law":false,"r":"m"},{"t":"PL","n":"1241","y":"2019","e":"Estabelece as diretrizes para o atendimento das  Comunidades Terapêuticas como Política Pública permanente no Território Nacional, garantindo o cuidado de qualidade aos pacientes com dependência química, em regime de residência transitória, e da outras providências.","d":"2019-02-27","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2019-05-07","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 08/05/19 PÁG 491.","id":"2193378","law":false,"r":"m"},{"t":"PL","n":"1239","y":"2019","e":"Proíbe a aplicação de recursos públicos, bem como o uso das estruturas e instituições da Administração Pública Direta ou Indireta, das Fundações, Autarquias e Empresas Públicas e Privadas prestadoras de serviços do Governo Federal, Estadual, Distrital e Municipal e outros, nas ações de difusão, incentivo e valoração da IDEOLOGIA DE GÊNERO.","d":"2019-02-27","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-25","ds":"Designada Relatora, Dep. Delegada Ione (PL-MG), para o PL 5941/2013, ao qual esta proposição está apensada.","id":"2193377","law":false,"r":"m"},{"t":"PL","n":"955","y":"2019","e":"Declara o evento \"MARCHA PARA JESUS\" Bem Imaterial e Cultural da Nação Brasileira e dá outras providências.","d":"2019-02-20","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Notificações","u":"2019-05-08","ds":"À CCULT o Memo nº 51/2019 - COPER, solicitando a devolução deste.","id":"2192556","law":false,"r":"m"},{"t":"PL","n":"925","y":"2019","e":"Institui o \"Dia Nacional do Orgulho Heterossexual\", a ser comemorado anualmente no terceiro domingo de dezembro.","d":"2019-02-20","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2019-03-21","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 22/03/19 PÁG 246.","id":"2192470","law":false,"r":"m"},{"t":"PLP","n":"18","y":"2019","e":"Institui o Orçamento Impositivo e dispõe sobre a execução orçamentária e financeira da programação incluída por emendas individuais dos Legislativos Municipais em Lei Orçamentária Anual, garantindo a oficialização desse direito a todos os VEREADORES do Brasil.","d":"2019-02-12","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2026-07-07","ds":"Deferido o Requerimento n. 2524/2026.","id":"2191570","law":false,"r":"m"},{"t":"PL","n":"8","y":"2019","e":"Institui o Orçamento Impositivo e dispõe sobre a execução orçamentária e financeira da programação incluída por emendas individuais dos Legislativos Municipais em Lei Orçamentária Anual, garantindo a oficialização desse direito a todos os VEREADORES do Brasil.","d":"2019-02-04","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2019-02-11","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 12/02/19 PÁG 42.","id":"2190414","law":false,"r":"m"},{"t":"PL","n":"2","y":"2019","e":"Proíbe o uso o nome e/ou título BÍBLIA ou BÍBLIA SAGRADA em qualquer publicação impressa e/ou eletrônica com conteúdo (livros, capítulos e versículos) diferente do já consagrado há milênios pelas diversas religiões Cristãs (Católicas, Evangélicas e outras que se orientam por este Livro - Bíblia)","d":"2019-02-04","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Retirada pelo(a) Autor(a)","u":"2022-03-22","ds":"Retirado o PL n. 2/2019, em razão do deferimento do Requerimento n. REQ 382/2022, nos termos do artigo 104, caput, combinado com o artigo 114, VII, ambos do RICD.","id":"2190408","law":false,"r":"m"},{"t":"PL","n":"1","y":"2019","e":"Declara a BÍBLIA SAGRADA como Patrimônio Nacional, Cultural e Imaterial do Brasil e da Humanidade.","d":"2019-02-04","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Apresentação de Proposição","u":"2025-08-26","ds":"Remessa ao Senado Federal por meio do Of. nº 274/2025/PS-GSE.","id":"2190407","law":false,"r":"m"}];
